<?php
require_once __DIR__.'/../includes/bootstrap.php';require_role('programme_manager');require_once __DIR__.'/_management_suite_helpers.php';
$user=current_user();$conn=Database::getConnection();$managerId=(int)($user['id']??$user['user_id']??0);if($managerId<=0){http_response_code(403);exit('Invalid Programme Manager account.');}
$currentPage='targets';$pageTitle='Programme Target & Performance';$errors=[];$ready=pm_table_exists($conn,'programme_targets');$programmes=pm_suite_programmes($conn,$managerId);$cohorts=pm_suite_cohorts($conn,$managerId);
if($_SERVER['REQUEST_METHOD']==='POST'){if(!validate_csrf())$errors[]='Session validation failed.';elseif(!$ready)$errors[]='Import database/programme_resource_targets_compliance.sql first.';else{$pid=(int)($_POST['programme_id']??0);$cid=(int)($_POST['cohort_id']??0);$name=trim((string)($_POST['target_name']??''));$desc=trim((string)($_POST['description']??''));$target=filter_var($_POST['target_value']??null,FILTER_VALIDATE_FLOAT);$actual=filter_var($_POST['actual_value']??null,FILTER_VALIDATE_FLOAT);$unit=trim((string)($_POST['unit_name']??'units'));$due=trim((string)($_POST['due_date']??''));$status=(string)($_POST['status']??'active');if(!pm_suite_valid_scope($conn,$pid,$cid,$managerId))$errors[]='Select a programme/cohort within your assigned scope.';if($name===''||mb_strlen($name)>160)$errors[]='Enter a target name.';if($target===false||$target<=0||$actual===false||$actual<0)$errors[]='Target must be above zero and actual must be non-negative.';if(!in_array($status,['active','achieved','at_risk','closed'],true))$errors[]='Invalid target status.';if($due!==''&&(!DateTime::createFromFormat('!Y-m-d',$due)||DateTime::createFromFormat('!Y-m-d',$due)->format('Y-m-d')!==$due))$errors[]='Invalid due date.';if(!$errors){$cv=$cid?:null;$dv=$due?:null;$s=$conn->prepare('INSERT INTO programme_targets(programme_id,cohort_id,target_name,description,target_value,actual_value,unit_name,due_date,status,created_by) VALUES(?,?,?,?,?,?,?,?,?,?)');if($s){$s->bind_param('iissddsssi',$pid,$cv,$name,$desc,$target,$actual,$unit,$dv,$status,$managerId);$ok=$s->execute();$s->close();if($ok){set_flash('success','Target saved','The performance target has been recorded.');safe_redirect('programme/targets.php');}}$errors[]='The target could not be saved.';}}}
$rows=[];$stats=['total'=>0,'achieved'=>0,'at_risk'=>0,'average'=>0];if($ready){$s=$conn->prepare('SELECT t.*,p.name programme_name,c.name cohort_name FROM programme_targets t JOIN programmes p ON p.id=t.programme_id LEFT JOIN cohorts c ON c.id=t.cohort_id WHERE p.programme_manager_id=? ORDER BY t.due_date IS NULL,t.due_date,t.id DESC');if($s){$s->bind_param('i',$managerId);$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();}foreach($rows as $r){$stats['total']++;if($r['status']==='achieved'||(float)$r['actual_value']>=(float)$r['target_value'])$stats['achieved']++;if($r['status']==='at_risk')$stats['at_risk']++;$stats['average']+=(float)$r['target_value']>0?min(100,((float)$r['actual_value']/(float)$r['target_value'])*100):0;}if($stats['total'])$stats['average']/=$stats['total'];}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($pageTitle)?></title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css"><link rel="stylesheet" href="<?=url('css/styles.css')?>"><link rel="stylesheet" href="<?=url('css/programme_manager_enhancements.css')?>"><link rel="stylesheet" href="<?=url('css/programme_management_suite.css')?>"></head><body class="dashboard-page"><div class="dashboard"><?php require __DIR__.'/sidebar.php';?><main class="dashboard__main"><?php require __DIR__.'/navbar.php';?><div class="pm-suite"><?=render_flashes()?><section class="pm-suite-hero"><div><span class="pm-suite-eyebrow">Objectives &amp; delivery</span><h1>Programme Target &amp; Performance Tracking</h1><p>Define measurable targets, record actual results and identify gaps against planned programme and cohort objectives.</p></div></section><?php foreach($errors as $er):?><div class="pm-suite-alert"><?=e($er)?></div><?php endforeach;?><?php if(!$ready):?><div class="pm-suite-notice">Import <code>database/programme_resource_targets_compliance.sql</code>.</div><?php endif;?>
<section class="pm-suite-kpis"><article class="pm-suite-kpi"><small>Targets tracked</small><strong><?=$stats['total']?></strong><span>Assigned programmes and cohorts</span></article><article class="pm-suite-kpi"><small>Achieved</small><strong><?=$stats['achieved']?></strong><span>Actual at or above target</span></article><article class="pm-suite-kpi"><small>At risk</small><strong><?=$stats['at_risk']?></strong><span>Flagged for attention</span></article><article class="pm-suite-kpi"><small>Average achievement</small><strong><?=number_format($stats['average'],1)?>%</strong><span>Actual compared with target</span></article></section>
<div class="pm-suite-grid"><section class="pm-suite-panel"><div class="pm-suite-panel-head"><h2>Define a performance target</h2><p>Use a consistent unit for target and actual values.</p></div><form method="post" class="pm-suite-form"><?=csrf_field()?><div class="pm-suite-field"><label>Programme</label><select name="programme_id" required><option value="">Select programme</option><?php foreach($programmes as $p):?><option value="<?=$p['id']?>"><?=e($p['name'])?></option><?php endforeach;?></select></div><div class="pm-suite-field"><label>Cohort (optional)</label><select name="cohort_id"><option value="0">Programme-wide</option><?php foreach($cohorts as $c):?><option value="<?=$c['id']?>"><?=e($c['programme_name'].' — '.$c['name'])?></option><?php endforeach;?></select></div><div class="pm-suite-field"><label>Target name</label><input name="target_name" maxlength="160" required placeholder="e.g. Candidate completion rate"></div><div class="pm-suite-field"><label>Description</label><textarea name="description" rows="2"></textarea></div><div class="pm-suite-two"><div class="pm-suite-field"><label>Target value</label><input type="number" min="0.01" step="0.01" name="target_value" required></div><div class="pm-suite-field"><label>Actual value</label><input type="number" min="0" step="0.01" name="actual_value" value="0" required></div></div><div class="pm-suite-two"><div class="pm-suite-field"><label>Unit</label><input name="unit_name" maxlength="40" value="units" required></div><div class="pm-suite-field"><label>Due date</label><input type="date" name="due_date"></div></div><div class="pm-suite-field"><label>Status</label><select name="status"><option value="active">Active</option><option value="at_risk">At risk</option><option value="achieved">Achieved</option><option value="closed">Closed</option></select></div><button class="pm-suite-btn" <?=$ready?'':'disabled'?>>Save target</button></form></section>
<section class="pm-suite-panel"><div class="pm-suite-panel-head"><h2>Performance targets</h2><p>Achievement is capped at 100% for the summary indicator; actual values remain visible.</p></div><div class="pm-suite-table-wrap"><table class="pm-suite-table"><thead><tr><th>Target / scope</th><th>Planned</th><th>Actual</th><th>Achievement</th><th>Gap</th><th>Status</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="6" class="pm-suite-empty">No targets have been recorded.</td></tr><?php else:foreach($rows as $r):$pct=(float)$r['target_value']>0?((float)$r['actual_value']/(float)$r['target_value'])*100:0;$gap=(float)$r['target_value']-(float)$r['actual_value'];?><tr><td><strong><?=e($r['target_name'])?></strong><span class="pm-suite-muted"><?=e($r['programme_name'])?><?=!empty($r['cohort_name'])?' / '.e($r['cohort_name']):' / Programme-wide'?></span></td><td><?=number_format((float)$r['target_value'],2)?> <?=e($r['unit_name'])?></td><td><?=number_format((float)$r['actual_value'],2)?></td><td><strong><?=number_format($pct,1)?>%</strong></td><td><?=number_format($gap,2)?></td><td><span class="pm-suite-pill <?=$gap<=0?'good':($r['status']==='at_risk'?'bad':'warn')?>"><?=e(ucwords(str_replace('_',' ',$r['status'])))?></span></td></tr><?php endforeach;endif;?></tbody></table></div></section></div></div></main></div><script src="<?=url('js/programme_manager_enhancements.js')?>"></script><script src="<?=url('js/original_pm_sidebar.js')?>"></script></body></html>
